from django.db import migrations, models


ZONE_FEATURES = {"red_zone": "RED", "orange_zone": "ORANGE"}


def move_zone_features(apps, schema_editor):
    """ผังสีเคยเก็บเป็นจุดเด่น ย้ายมาเป็นช่องของตัวเองเพื่อให้กรองและเลือกได้ครบทุกสี"""
    Property = apps.get_model("properties", "Property")
    for prop in Property.objects.only("features", "zoning"):
        zones = [key for key in prop.features if key in ZONE_FEATURES]
        if zones:
            prop.zoning = ZONE_FEATURES[zones[0]]
            prop.features = [key for key in prop.features if key not in ZONE_FEATURES]
            prop.save(update_fields=["features", "zoning"])


def restore_zone_features(apps, schema_editor):
    Property = apps.get_model("properties", "Property")
    keys = {value: key for key, value in ZONE_FEATURES.items()}
    for prop in Property.objects.filter(zoning__in=keys).only("features", "zoning"):
        prop.features = [*prop.features, keys[prop.zoning]]
        prop.save(update_fields=["features"])


